/* Pure deterministic educational logistics ledger. Quantities: integral boxes; route units: km. */
(function(root){'use strict';const copy=x=>JSON.parse(JSON.stringify(x));
const need=(x,m)=>{if(!x)throw Error(m)};const num=(x,min,max)=>{x=Number(x);need(Number.isFinite(x)&&x>=min&&x<=max,'数值超出范围');return x};const qty=x=>{x=num(x,1,100000);need(Number.isInteger(x),'数量必须为整数');return x};const txt=(x,n=100)=>{x=String(x??'').trim();need(x&&x.length<=n,'请填写有效文本');return x};
function initial(){return {schema:1,seq:1,clock:0,products:[],vehicles:[],tasks:[],ledger:[],alarms:[],telemetry:[],calendar:[],reports:[]}}
function id(s,p){return p+String(s.seq++).padStart(4,'0')}
function available(s,p){return p.stock-s.tasks.filter(t=>t.product===p.id&&t.status==='planned').reduce((n,t)=>n+t.qty,0)}
function log(s,type,detail,delta=0,product=''){s.ledger.unshift({id:id(s,'L'),at:new Date().toISOString(),minute:s.clock,type,detail,delta,product})}
function apply(state,action,d={}){let s=copy(state);need(s?.schema===1,'物流数据版本无效');
if(action==='receive'){const sku=txt(d.sku,40);let p=s.products.find(x=>x.sku===sku);const q=qty(d.qty);if(!p){p={id:id(s,'P'),sku,name:txt(d.name),zone:txt(d.zone,40),stock:0,min:num(d.min,-50,50),max:num(d.max,-50,80),humidity:num(d.humidity,1,100)};need(p.min<p.max,'最低温度必须小于最高温度');s.products.push(p)}p.stock+=q;log(s,'入库',p.sku+' · '+p.name,q,p.id)}
else if(action==='vehicle'){const plate=txt(d.plate,30);need(!s.vehicles.some(v=>v.plate===plate),'车牌/编号已存在');s.vehicles.push({id:id(s,'V'),plate,driver:txt(d.driver,40),capacity:qty(d.capacity),cold:!!d.cold});log(s,'车辆建档',plate)}
else if(action==='plan'){const p=s.products.find(x=>x.id===d.product),v=s.vehicles.find(x=>x.id===d.vehicle);need(p&&v,'请选择货品与车辆');const q=qty(d.qty);need(q<=available(s,p),'可用库存不足');need(q<=v.capacity,'超过车辆容量');need(v.cold,'冷链运输需要冷藏车辆');need(!s.tasks.some(t=>t.vehicle===v.id&&['planned','running','arrived'].includes(t.status)),'车辆已有未完成任务');const distance=num(d.distance,1,2000),duration=num(d.duration,1,10000);let t={id:id(s,'T'),product:p.id,vehicle:v.id,qty:q,destination:txt(d.destination,80),distance,duration,status:'planned',progress:0,x:0,y:0,start:null,elapsed:0,temp:(p.min+p.max)/2,humidity:50,online:true};s.tasks.unshift(t);log(s,'运输计划',t.id+' 预留 '+q+' 箱 '+p.sku)}
else if(action==='dispatch'){const t=s.tasks.find(t=>t.id===d.id);need(t&&t.status==='planned','任务不可重复发运');const p=s.products.find(p=>p.id===t.product);need(p.stock>=t.qty,'库存不足');p.stock-=t.qty;t.status='running';t.start=s.clock;log(s,'出库发运',t.id,-t.qty,p.id)}
else if(action==='cancel'){const t=s.tasks.find(t=>t.id===d.id);need(t&&t.status==='planned','仅可取消待发运计划');t.status='cancelled';log(s,'计划取消',t.id+' 已释放库存预留')}
else if(action==='sample'){const t=s.tasks.find(t=>t.id===d.id);need(t&&t.status==='running','请选择运输中的任务');const p=s.products.find(p=>p.id===t.product);const minutes=num(d.minutes,1,120);s.clock+=minutes;t.elapsed=s.clock-t.start;t.temp=num(d.temp,-70,100);t.humidity=num(d.humidity,0,100);t.online=!!d.online;const step=num(d.distance,0,t.distance),offset=num(d.offset,-100,100);t.progress=Math.min(t.distance,t.progress+step);t.x=t.progress;t.y=offset;const sample={id:id(s,'S'),task:t.id,minute:s.clock,temp:t.temp,humidity:t.humidity,online:t.online,x:t.x,y:t.y};s.telemetry.push(sample);const checks=[['温度越界',t.temp<p.min||t.temp>p.max,`${t.temp}°C / ${p.min}~${p.max}°C`],['湿度越界',t.humidity>p.humidity,`${t.humidity}% / 上限 ${p.humidity}%`],['路线偏离',Math.abs(offset)>2,`横向偏离 ${Math.abs(offset)} km`],['设备离线',!t.online,'本次模拟采样未上线']];for(const other of s.tasks.filter(v=>v.status==='running')){other.elapsed=s.clock-other.start;if(other.elapsed>other.duration&&!s.alarms.some(a=>a.task===other.id&&a.type==='运输超时'&&!a.resolved)){s.alarms.unshift({id:id(s,'A'),task:other.id,type:'运输超时',detail:other.elapsed+' / '+other.duration+' min',minute:s.clock,ack:false,resolved:false})}}
for(const [type,bad,detail] of checks){const previous=s.alarms.find(a=>a.task===t.id&&a.type===type&&!a.resolved);if(bad&&!previous)s.alarms.unshift({id:id(s,'A'),task:t.id,type,detail,minute:s.clock,ack:false,resolved:false});if(!bad&&previous){previous.resolved=true;previous.resolvedMinute=s.clock}}
if(t.progress>=t.distance&&Math.abs(offset)<=2){t.status='arrived';log(s,'到达待签收',t.id)}log(s,'模拟采样',t.id+' '+t.progress.toFixed(1)+'/'+t.distance+' km')}
else if(action==='deliver'){const t=s.tasks.find(t=>t.id===d.id);need(t&&t.status==='arrived','货物尚未到达规划终点');need(txt(d.receiver,40),'请输入签收人');t.receiver=d.receiver.trim();t.status='delivered';t.deliveredAt=new Date().toISOString();log(s,'交付签收',t.id+' · '+t.receiver)}
else if(action==='ack'){const a=s.alarms.find(a=>a.id===d.id);need(a&&!a.ack,'告警不存在或已确认');a.ack=true;a.note=txt(d.note,300);log(s,'告警确认',a.id+' · '+a.note)}
else if(action==='calendar'){s.calendar.push({id:id(s,'C'),title:txt(d.title),date:txt(d.date,20),className:txt(d.className,80)});need(/^\d{4}-\d{2}-\d{2}$/.test(d.date),'日期格式无效')}
else if(action==='report'){need(s.tasks.some(t=>t.id===d.task),'关联运单不存在');s.reports.unshift({id:id(s,'R'),title:txt(d.title),learner:txt(d.learner,40),observations:txt(d.observations,5000),at:new Date().toISOString(),task:txt(d.task,40),evidence:copy({tasks:s.tasks,ledger:s.ledger,alarms:s.alarms,telemetry:s.telemetry})});}
else throw Error('未知作业');return s}
function demo(base=initial()){let s=copy(base);s=apply(s,'receive',{sku:'SIM-FRESH-01',name:'冷藏鲜果（样例）',zone:'冷藏 A-01',qty:120,min:2,max:8,humidity:85});s=apply(s,'receive',{sku:'SIM-DAIRY-02',name:'乳制品（样例）',zone:'冷藏 B-02',qty:80,min:2,max:6,humidity:80});if(!s.vehicles.some(v=>v.plate==='SIM-冷链01'))s=apply(s,'vehicle',{plate:'SIM-冷链01',driver:'仿真驾驶员 A',capacity:60,cold:true});if(!s.vehicles.some(v=>v.plate==='SIM-冷链02'))s=apply(s,'vehicle',{plate:'SIM-冷链02',driver:'仿真驾驶员 B',capacity:100,cold:true});return s}
const api={initial,apply,available,demo};if(typeof module!=='undefined')module.exports=api;root.LogisticsCore=api;
})(typeof window!=='undefined'?window:globalThis);
